import secrets

def split_secret(secret, t, n, prime=2**127-1):
    if t > n:
        raise ValueError('t must be <= n')
    if secret >= prime:
        raise ValueError('Secret must be < prime')
    coeffs = [secret] + [secrets.randbelow(prime) for _ in range(t-1)]
    shares = []
    for x in range(1, n+1):
        y = 0
        for power, coeff in enumerate(coeffs):
            y = (y + coeff * pow(x, power, prime)) % prime
        shares.append((x, y))
    return shares

def recover_secret(shares, prime=2**127-1):
    if len(shares) < 1:
        raise ValueError('Need at least one share')
    secret = 0
    for i, (xi, yi) in enumerate(shares):
        numerator = 1
        denominator = 1
        for j, (xj, _) in enumerate(shares):
            if i != j:
                numerator = (numerator * (-xj)) % prime
                denominator = (denominator * (xi - xj)) % prime
        lagrange_coeff = (yi * numerator * pow(denominator, -1, prime)) % prime
        secret = (secret + lagrange_coeff) % prime
    return secret
